INSERT INTO `goods_spu` (`id`, `name`, `sub_title`, `introduction`, `spu_urls`, `status`, `sales_volume`, `category_first_id`, `category_second_id`, `brand_id`, `create_time`, `update_time`, `del_flag`, `description`, `enable_specs`, `tenant_id`, `create_by`, `update_by`, `stock`, `freight_type`, `fixed_freight_price`, `sales_price`, `original_price`, `cost_price`, `attr_tags`) VALUES ('97700000000000000001', '夏黑无籽葡萄 约500g/盒', '粒粒紧实 无籽清甜', '<p>一串下去不用吐籽，追剧时抓一把，<span style="color:#8a3a6a;font-weight:bold">快乐不用挑</span>。</p>', 'http://localhost:9999/boot/file/local/1590229800633634816/f0bf3ad5-522e-50ef-a5ec-d8b7f9ab04b4.jpg', '1', 40, '9710000000000000001', '97600000000000000001', '9730000000000000002', NOW(), NOW(), '0', '<p>【商品名称】夏黑无籽葡萄 约500g/盒</p><p>【包装规格】约500g/盒</p><p>【储存方式】冷藏保鲜</p><p>【温馨提示】请以实物为准，生鲜商品因批次不同可能存在差异，介意慎拍。</p>', '0', '1590229800633634816', 'system', NULL, 153, '0', NULL, 12.90, 15.90, 7.74, '[{"key":"attr-1","icon":"snowflake","tone":"green","label":"储存条件","value":"冷藏保鲜","linkType":"none"},{"key":"attr-2","icon":"trophy","tone":"blue","label":"特色","value":"产地直采","linkType":"none"},{"key":"attr-3","icon":"star-filled","tone":"orange","label":"系列","value":"浆果葡萄","linkType":"none"}]');
