-- 悦航购商品目录大规模扩充（Boot 单体模式）
--
-- 目标库：aryn_boot
-- 内容：35 个新二级类目（976 前缀）+ 241 个新 SPU（977 前缀，含 7 个薄弱二级类目补货 27 个）
--       + 241 个默认 SKU（978 前缀）+ 241 条素材登记（979 前缀），全部挂主租户 1590229800633634816
-- 特性：可重复执行；仅按 976/977/978/979 前缀清理本脚本自身的种子数据，不触碰存量业务数据
-- 执行：mysql -u root -p aryn_boot < 178goods_catalog_expansion_incremental.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 清理本脚本历史种子（幂等） ----------
DELETE FROM `goods_sku` WHERE `id` LIKE '978%%';
DELETE FROM `goods_spu` WHERE `id` LIKE '977%%';
DELETE FROM `goods_category` WHERE `id` LIKE '976%%';
DELETE FROM `sys_material` WHERE `id` LIKE '979%%';

-- ---------- 1. 新二级类目（35 个，976 前缀） ----------

-- ---------- 2. 新 SPU（241 个，977 前缀） ----------

-- ---------- 3. 默认 SKU（241 个，978 前缀） ----------

-- ---------- 4. 素材库登记（241 条，979 前缀） ----------

-- ---------- 5. 自检：四表本脚本种子行数（预期 35 / 241 / 241 / 241） ----------
SELECT 'goods_category' AS tbl, COUNT(*) AS cnt FROM `goods_category` WHERE `id` LIKE '976%%'
UNION ALL SELECT 'goods_spu', COUNT(*) FROM `goods_spu` WHERE `id` LIKE '977%%'
UNION ALL SELECT 'goods_sku', COUNT(*) FROM `goods_sku` WHERE `id` LIKE '978%%'
UNION ALL SELECT 'sys_material', COUNT(*) FROM `sys_material` WHERE `id` LIKE '979%%';

SET FOREIGN_KEY_CHECKS = 1;
